insert into etapas (id, orden, nombre, corto, icono, color, rango, complementaria, descripcion, indicadores, preguntas) values ('embarazo', 0, 'Embarazo y preparación familiar', 'Embarazo', '🤰', '#9B4DE0', 'Antes del nacimiento', true, 'Ruta educativa complementaria: hábitos de la madre gestante, descanso, red de apoyo y lo que viene en los primeros meses.', '[{"clave":"sueno","etiqueta":"Horas de sueño por noche","unidad":"h","min":0,"max":14,"paso":0.5,"meta":{"tipo":"min","valor":7},"peso":25},{"clave":"frutas_verduras","etiqueta":"Porciones de frutas y verduras al día","unidad":"porciones","min":0,"max":10,"paso":1,"meta":{"tipo":"min","valor":3},"peso":25},{"clave":"agua","etiqueta":"Vasos de agua al día","unidad":"vasos","min":0,"max":15,"paso":1,"meta":{"tipo":"min","valor":8},"peso":20},{"clave":"movimiento","etiqueta":"Minutos de caminata o actividad suave al día","unidad":"min","min":0,"max":180,"paso":5,"meta":{"tipo":"min","valor":20},"peso":20},{"clave":"descanso","etiqueta":"Días de la semana con un momento de descanso","unidad":"días","min":0,"max":7,"paso":1,"meta":{"tipo":"min","valor":4},"peso":10}]'::jsonb, '[{"id":"q1","texto":"¿En qué momento del embarazo están?","opciones":[{"t":"Primer trimestre"},{"t":"Segundo trimestre"},{"t":"Tercer trimestre","nota":"En el tercer trimestre conviene adelantar el plan para las primeras semanas en casa (semana 11 de la ruta)."}]},{"id":"q2","texto":"¿Cómo va el descanso por las noches?","opciones":[{"t":"Duermo bien"},{"t":"Me despierto varias veces","nota":"El descanso es uno de los temas que la ruta trabaja desde la semana 3."},{"t":"Duermo muy poco","nota":"El descanso es uno de los temas que la ruta trabaja desde la semana 3."}]},{"id":"q3","texto":"¿Quién acompaña en casa durante el embarazo?","opciones":[{"t":"Pareja o familia cercana"},{"t":"Red pequeña","nota":"La semana 6 ayuda a organizar la red de apoyo para después del nacimiento."},{"t":"Estoy sola","nota":"La semana 6 ayuda a organizar la red de apoyo; conviene pedir orientación personalizada."}]},{"id":"q4","texto":"¿Qué tipo de acompañamiento te gustaría?","opciones":[{"t":"Información clara cada semana"},{"t":"Alguien que revise mi avance","nota":"El seguimiento profesional permite que una persona valide tus registros y recomendaciones."},{"t":"Las dos cosas","nota":"El seguimiento profesional permite que una persona valide tus registros y recomendaciones."}]}]'::jsonb)
insert into etapas (id, orden, nombre, corto, icono, color, rango, complementaria, descripcion, indicadores, preguntas) values ('0-6m', 1, '0 a 6 meses', '0–6 meses', '👶', '#2EC4D6', 'Desde el nacimiento hasta los 6 meses', false, 'Lactancia o fórmula a demanda, sueño seguro, contacto y movimiento libre. Sin pantallas.', '[{"clave":"tomas","etiqueta":"Tomas de leche al día (pecho o fórmula)","unidad":"tomas","min":0,"max":15,"paso":1,"meta":{"tipo":"min","valor":8},"peso":30},{"clave":"sueno_total","etiqueta":"Horas de sueño en 24 horas (incluye siestas)","unidad":"h","min":0,"max":24,"paso":0.5,"meta":{"tipo":"min","valor":14},"peso":25},{"clave":"boca_abajo","etiqueta":"Minutos de tiempo boca abajo al día (despierto y vigilado)","unidad":"min","min":0,"max":120,"paso":5,"meta":{"tipo":"min","valor":10},"peso":20},{"clave":"contacto","etiqueta":"Momentos de contacto, voz y mirada al día","unidad":"momentos","min":0,"max":20,"paso":1,"meta":{"tipo":"min","valor":5},"peso":15},{"clave":"pantallas","etiqueta":"Minutos de exposición a pantallas al día","unidad":"min","min":0,"max":300,"paso":5,"meta":{"tipo":"max","valor":0},"peso":10}]'::jsonb, '[{"id":"q1","texto":"¿Cómo se alimenta el bebé hoy?","opciones":[{"t":"Solo pecho"},{"t":"Pecho y fórmula"},{"t":"Solo fórmula"},{"t":"Tengo dudas sobre las tomas","nota":"Las semanas 2 y 8 trabajan las tomas a demanda y las señales de hambre y saciedad."}]},{"id":"q2","texto":"¿Cómo duerme el bebé?","opciones":[{"t":"Duerme y despierta con un ritmo parecido cada día"},{"t":"Todavía no hay ritmo","nota":"La semana 6 propone rutinas suaves de día y noche."},{"t":"Nos preocupa dónde o cómo duerme","nota":"La semana 3 (sueño seguro) es prioritaria para su familia."}]},{"id":"q3","texto":"¿Cuánto tiempo pasa el bebé boca abajo, despierto y vigilado?","opciones":[{"t":"Varias veces al día"},{"t":"A veces"},{"t":"Casi nunca","nota":"La semana 4 explica el tiempo boca abajo y el movimiento libre."}]},{"id":"q4","texto":"¿Qué necesitan más en casa?","opciones":[{"t":"Información sencilla cada semana"},{"t":"Descanso para quien cuida","nota":"La semana 9 está dedicada a cuidar a quien cuida."},{"t":"Que alguien revise cómo vamos","nota":"El seguimiento profesional permite validar registros y recomendaciones."}]}]'::jsonb)
insert into etapas (id, orden, nombre, corto, icono, color, rango, complementaria, descripcion, indicadores, preguntas) values ('6-12m', 2, '6 a 12 meses', '6–12 meses', '🍼', '#E7A14A', 'De los 6 a los 12 meses', false, 'Primeros alimentos uno a la vez, texturas, agua en vasito, juego en el piso y sueño con siestas.', '[{"clave":"sueno_total","etiqueta":"Horas de sueño en 24 horas (incluye siestas)","unidad":"h","min":0,"max":24,"paso":0.5,"meta":{"tipo":"min","valor":13},"peso":25},{"clave":"alimentos_nuevos","etiqueta":"Alimentos nuevos probados en la semana","unidad":"alimentos","min":0,"max":15,"paso":1,"meta":{"tipo":"min","valor":2},"peso":25},{"clave":"tomas","etiqueta":"Tomas de leche al día","unidad":"tomas","min":0,"max":12,"paso":1,"meta":{"tipo":"min","valor":4},"peso":15},{"clave":"juego_piso","etiqueta":"Minutos de juego en el piso al día","unidad":"min","min":0,"max":240,"paso":5,"meta":{"tipo":"min","valor":30},"peso":25},{"clave":"pantallas","etiqueta":"Minutos de exposición a pantallas al día","unidad":"min","min":0,"max":300,"paso":5,"meta":{"tipo":"max","valor":0},"peso":10}]'::jsonb, '[{"id":"q1","texto":"¿Ya empezaron con alimentos distintos a la leche?","opciones":[{"t":"Sí, varios"},{"t":"Apenas empezamos"},{"t":"Todavía no","nota":"Las semanas 2 y 3 acompañan los primeros alimentos y las texturas."}]},{"id":"q2","texto":"¿Cómo van las siestas y la noche?","opciones":[{"t":"Bien, con rutina"},{"t":"Siestas irregulares","nota":"La semana 7 ordena siestas y noche."},{"t":"Se despierta mucho","nota":"La semana 7 ordena siestas y noche."}]},{"id":"q3","texto":"¿Cuánto tiempo juega en el piso al día?","opciones":[{"t":"Más de 30 minutos"},{"t":"Entre 10 y 30 minutos"},{"t":"Menos de 10 minutos","nota":"La semana 6 propone juego en el piso y gateo con objetos de casa."}]},{"id":"q4","texto":"¿Hay pantallas encendidas cerca del bebé?","opciones":[{"t":"No"},{"t":"A veces","nota":"A esta edad se recomienda cero pantallas; la semana 8 lo trabaja sin culpas."},{"t":"Casi siempre","nota":"A esta edad se recomienda cero pantallas; la semana 8 lo trabaja sin culpas."}]}]'::jsonb)
insert into etapas (id, orden, nombre, corto, icono, color, rango, complementaria, descripcion, indicadores, preguntas) values ('1-3a', 3, '1 a 3 años', '1–3 años', '🧸', '#E8637A', 'De 1 a 3 años', false, 'Agua, frutas y verduras, juego activo, rutina de sueño, berrinches y pantallas con medida.', '[{"clave":"sueno","etiqueta":"Horas de sueño en 24 horas (incluye siesta)","unidad":"h","min":0,"max":20,"paso":0.5,"meta":{"tipo":"min","valor":11},"peso":25},{"clave":"frutas_verduras","etiqueta":"Porciones de frutas y verduras al día","unidad":"porciones","min":0,"max":10,"paso":1,"meta":{"tipo":"min","valor":3},"peso":25},{"clave":"agua","etiqueta":"Vasos de agua al día","unidad":"vasos","min":0,"max":12,"paso":1,"meta":{"tipo":"min","valor":4},"peso":15},{"clave":"juego_activo","etiqueta":"Minutos de juego activo al día","unidad":"min","min":0,"max":300,"paso":5,"meta":{"tipo":"min","valor":60},"peso":20},{"clave":"pantallas","etiqueta":"Minutos de pantallas al día","unidad":"min","min":0,"max":600,"paso":5,"meta":{"tipo":"max","valor":60},"peso":15}]'::jsonb, '[{"id":"q1","texto":"¿Qué toma cuando tiene sed?","opciones":[{"t":"Agua"},{"t":"Agua y jugos"},{"t":"Jugos o refrescos","nota":"La semana 3 («Agua primero») ayuda a cambiar bebidas azucaradas sin pleitos."}]},{"id":"q2","texto":"¿Cuántas porciones de frutas y verduras come al día?","opciones":[{"t":"3 o más"},{"t":"1 o 2","nota":"La semana 4 propone el juego de colores para probar frutas y verduras."},{"t":"Casi ninguna","nota":"La semana 4 propone el juego de colores para probar frutas y verduras."}]},{"id":"q3","texto":"¿Cuánto tiempo de pantallas tiene al día?","opciones":[{"t":"Nada o menos de media hora"},{"t":"Alrededor de una hora"},{"t":"Más de una hora","nota":"La semana 7 ayuda a poner medida a las pantallas con acuerdos sencillos."}]},{"id":"q4","texto":"¿Cuál es el mayor reto en casa hoy?","opciones":[{"t":"Que coma variado"},{"t":"Dormir","nota":"La semana 6 trabaja la rutina de noche."},{"t":"Los berrinches","nota":"La semana 8 distingue hambre, cansancio y emociones."},{"t":"Que se mueva más","nota":"La semana 5 propone moverse jugando."}]}]'::jsonb)
insert into etapas (id, orden, nombre, corto, icono, color, rango, complementaria, descripcion, indicadores, preguntas) values ('3-6a', 4, '3 a 6 años', '3–6 años', '🧒', '#5B6FE6', 'De 3 a 6 años', false, 'Plato de colores, 60 minutos de juego activo, hora fija para dormir, acuerdos de pantallas y refrigerio escolar.', '[{"clave":"sueno","etiqueta":"Horas de sueño por noche","unidad":"h","min":0,"max":16,"paso":0.5,"meta":{"tipo":"min","valor":10},"peso":25},{"clave":"frutas_verduras","etiqueta":"Porciones de frutas y verduras al día","unidad":"porciones","min":0,"max":10,"paso":1,"meta":{"tipo":"min","valor":3},"peso":25},{"clave":"agua","etiqueta":"Vasos de agua al día","unidad":"vasos","min":0,"max":12,"paso":1,"meta":{"tipo":"min","valor":5},"peso":15},{"clave":"juego_activo","etiqueta":"Minutos de juego activo al día","unidad":"min","min":0,"max":300,"paso":5,"meta":{"tipo":"min","valor":60},"peso":20},{"clave":"pantallas","etiqueta":"Minutos de pantallas al día","unidad":"min","min":0,"max":600,"paso":5,"meta":{"tipo":"max","valor":60},"peso":15}]'::jsonb, '[{"id":"q1","texto":"¿Desayuna antes de salir de casa?","opciones":[{"t":"Todos los días"},{"t":"Algunos días","nota":"La semana 2 propone desayunos sencillos y rápidos."},{"t":"Casi nunca","nota":"La semana 2 propone desayunos sencillos y rápidos."}]},{"id":"q2","texto":"¿Cuánto juego activo tiene al día?","opciones":[{"t":"Una hora o más"},{"t":"Media hora","nota":"La semana 5 ayuda a llegar a 60 minutos de juego activo."},{"t":"Casi nada","nota":"La semana 5 ayuda a llegar a 60 minutos de juego activo."}]},{"id":"q3","texto":"¿A qué hora se duerme entre semana?","opciones":[{"t":"Antes de las 9"},{"t":"Entre 9 y 10","nota":"La semana 6 fija una hora de dormir y una rutina corta."},{"t":"Después de las 10","nota":"La semana 6 fija una hora de dormir y una rutina corta."}]},{"id":"q4","texto":"¿Cómo son las pantallas en casa?","opciones":[{"t":"Con horario y acompañadas"},{"t":"Sin horario fijo","nota":"La semana 7 construye acuerdos de pantallas en familia."},{"t":"Es un tema de conflicto","nota":"La semana 7 construye acuerdos de pantallas en familia."}]}]'::jsonb)
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 1, 'Punto de partida', 'Conocer los hábitos actuales sin cambiar nada todavía.', 'Antes de proponer cambios conviene observar: cómo duermes, qué comes, cuánto te mueves y cómo te sientes. Es el punto de comparación de toda la ruta.', 'Anotar durante tres días qué comiste, cuánto dormiste y cómo te sentiste.', 'Libreta o notas del celular.', 'La libreta de tres días, ¿quedó?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 2, 'Comer para dos no es comer el doble', 'Entender qué cambia en la alimentación durante el embarazo.', 'El cuerpo necesita más calidad, no el doble de cantidad: verduras, frutas, proteína y granos enteros; menos azúcar añadida.', 'Agregar una verdura o fruta a dos comidas del día durante la semana.', 'Ninguno.', '¿Lograste agregar fruta o verdura a dos comidas?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 3, 'Agua y descanso', 'Tomar suficiente agua y proteger el descanso.', 'La hidratación y el descanso ayudan con el cansancio, la circulación y el ánimo. Pequeños cambios de rutina hacen diferencia.', 'Tener una botella de agua a la mano y apartar 15 minutos de descanso al día.', 'Botella de agua.', '¿Cuántos días apartaste el descanso?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 4, 'Moverse con calma', 'Incorporar movimiento suave y seguro.', 'Caminar y estirarse, con la autorización de tu control prenatal, ayuda a dormir mejor y a prepararse para el parto.', 'Caminar 20 minutos al menos tres días de la semana.', 'Calzado cómodo.', '¿Cuántos días caminaste?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 5, 'Dormir mejor', 'Encontrar posturas y rutinas para descansar.', 'Dormir de lado con una almohada entre las rodillas, cenar ligero y bajar las pantallas antes de dormir mejora el descanso.', 'Probar la rutina de noche (cena ligera, sin pantallas, almohada) durante cinco noches.', 'Almohada adicional.', '¿Notaste cambios en el descanso?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 6, 'Red de apoyo', 'Definir quién acompañará en las primeras semanas.', 'Las primeras semanas en casa son más fáciles con apoyos claros: quién ayuda con la comida, el aseo, los hermanos, los traslados.', 'Hacer una lista de personas y tareas en las que pueden apoyar, y hablarlo con ellas.', 'Hoja de papel.', '¿Ya tienen la lista de apoyos?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 7, 'El espacio del bebé', 'Preparar un espacio seguro y sencillo para dormir.', 'El bebé necesita una superficie firme, sin almohadas ni cobijas sueltas, en la misma habitación que los adultos los primeros meses.', 'Revisar y preparar el espacio donde dormirá el bebé.', 'Cuna o moisés con colchón firme.', '¿El espacio para dormir ya está listo?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 8, 'Lactancia: lo que conviene saber antes', 'Conocer lo básico de la lactancia antes del nacimiento.', 'Saber cómo se acomoda el bebé, qué es normal los primeros días y dónde pedir ayuda evita abandonar la lactancia por dudas.', 'Ver el material de lactancia y anotar dos dudas para el control prenatal.', 'Guía de lactancia (ejemplo).', '¿Anotaste tus dudas para el control?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 9, 'Señales de alerta y control prenatal', 'Saber qué señales requieren atención médica.', 'Sangrado, dolor intenso, dolor de cabeza fuerte, hinchazón repentina o menos movimientos del bebé requieren revisión inmediata.', 'Guardar el teléfono de emergencia y confirmar la fecha del próximo control.', 'Teléfono de la unidad de salud.', '¿Tienes el próximo control agendado?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 10, 'Las emociones del embarazo', 'Reconocer y hablar de lo que se siente.', 'Alegría, miedo y cansancio conviven. Nombrar lo que se siente y hablarlo con alguien de confianza protege la salud emocional.', 'Dedicar un momento del día a escribir o contar cómo te sentiste.', 'Libreta.', '¿Cuántos días lo hiciste?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 11, 'Plan para las primeras semanas', 'Tener un plan sencillo para la llegada del bebé.', 'Un plan de comidas, turnos de descanso, visitas y traslados reduce el estrés de las primeras semanas.', 'Escribir el plan de las dos primeras semanas en casa con la red de apoyo.', 'Lista de la semana 6.', '¿El plan quedó escrito?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('embarazo', 12, 'Lo que ya tienen listo', 'Cerrar la ruta y pasar a la etapa 0–6 meses.', 'Revisamos lo que la familia ya preparó y lo que sigue cuando nazca el bebé: el programa continúa con la etapa 0 a 6 meses.', 'Repasar la lista de la ruta y celebrar lo preparado.', 'Ninguno.', '¿Se sienten preparados para lo que sigue?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 1, 'Conocer el ritmo del bebé', 'Observar cómo come, duerme y llora el bebé.', 'Cada bebé tiene su ritmo. Observar sin juzgar durante unos días ayuda a reconocer señales de hambre, sueño y malestar.', 'Anotar durante tres días las tomas, los sueños y los ratos de llanto.', 'Libreta o notas del celular.', '¿Pudiste anotar los tres días?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 2, 'Tomas a demanda', 'Alimentar cuando el bebé lo pide.', 'Los recién nacidos comen entre 8 y 12 veces al día. Las señales tempranas de hambre (mover la boca, llevarse las manos) son mejores que esperar el llanto.', 'Responder a las señales tempranas de hambre durante una semana.', 'Ninguno.', '¿Reconociste señales antes del llanto?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 3, 'Sueño seguro', 'Dormir al bebé de forma segura.', 'Boca arriba, en superficie firme, sin almohadas ni cobijas sueltas, sin humo y en la habitación de los adultos.', 'Revisar el espacio de sueño con la lista de sueño seguro.', 'Lista de sueño seguro (ejemplo).', '¿El espacio cumple la lista?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 4, 'Tiempo boca abajo', 'Fortalecer cuello y espalda con tiempo boca abajo.', 'Despierto y vigilado, unos minutos varias veces al día. Se va aumentando poco a poco.', 'Tres ratos de tiempo boca abajo al día, de 2 a 5 minutos.', 'Tapete o cobija en el piso.', '¿Cuántos ratos lograron al día?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 5, 'Contacto, voz y mirada', 'Fortalecer el vínculo con el bebé.', 'Hablarle, cantarle y mirarlo mientras se le atiende construye vínculo y lenguaje. No se necesita nada especial.', 'Hablarle o cantarle en cada cambio de pañal durante la semana.', 'Ninguno.', '¿Lo hicieron en la mayoría de los cambios?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 6, 'Rutinas suaves de día y noche', 'Diferenciar el día de la noche.', 'Luz y actividad de día; poca luz, voz baja y menos estímulo de noche. Ayuda al bebé a organizar el sueño.', 'Aplicar la rutina de noche (luz baja, voz suave) durante cinco noches.', 'Lámpara tenue.', '¿Notaron diferencia en las noches?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 7, 'Cero pantallas, mucho rostro', 'Evitar pantallas en esta etapa.', 'Antes de los 2 años no se recomiendan pantallas. El rostro y la voz de quien cuida son el mejor estímulo.', 'Apagar las pantallas mientras se alimenta o se juega con el bebé.', 'Ninguno.', '¿Hubo pantallas durante las tomas?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 8, 'Señales de hambre y saciedad', 'Respetar cuándo quiere y cuándo ya no.', 'Girar la cara, soltar el pecho o el biberón y relajar las manos son señales de saciedad; respetarlas evita sobrealimentar.', 'Observar y anotar señales de saciedad en tres tomas al día.', 'Libreta.', '¿Identificaron señales de saciedad?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 9, 'Cuidar a quien cuida', 'Proteger el descanso y el ánimo de madres y padres.', 'Dormir cuando el bebé duerme, aceptar ayuda y comer bien no es un lujo: es parte del cuidado del bebé.', 'Acordar con la red de apoyo dos ratos de descanso para quien cuida.', 'Lista de apoyos.', '¿Lograron los ratos de descanso?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 10, 'Juego sencillo', 'Estimular con objetos de casa.', 'Sonajas, telas de texturas, canciones y espejos. Pocos minutos, varias veces al día.', 'Un rato de juego con texturas o canciones cada día.', 'Telas, sonaja, espejo.', '¿Cuántos días jugaron?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 11, 'Lo que viene: primeros alimentos', 'Prepararse para la alimentación complementaria.', 'Alrededor de los 6 meses, cuando se sienta con apoyo y muestra interés, se inician los alimentos. La leche sigue siendo la base.', 'Revisar las señales de que el bebé está listo y anotar dudas para la consulta.', 'Guía de primeros alimentos (ejemplo).', '¿Anotaron sus dudas?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('0-6m', 12, 'Cierre de la etapa', 'Celebrar lo logrado y pasar a 6–12 meses.', 'Repasamos los hábitos construidos: sueño seguro, tomas a demanda, tiempo boca abajo y vínculo. El programa continúa en la siguiente etapa.', 'Completar la evaluación de cierre y celebrar en familia.', 'Ninguno.', '¿Qué hábito les costó menos trabajo?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 1, 'Punto de partida', 'Observar hábitos de alimentación, sueño y juego.', 'Al iniciar la etapa observamos sin cambiar nada: qué come, cuánto duerme, cuánto juega en el piso.', 'Anotar tres días de tomas, alimentos, siestas y juego.', 'Libreta.', '¿Quedaron los tres días anotados?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 2, 'Primeros alimentos, uno a la vez', 'Introducir alimentos nuevos con calma.', 'Un alimento nuevo cada dos o tres días permite ver cómo reacciona el bebé. Sin sal ni azúcar añadida.', 'Ofrecer dos alimentos nuevos esta semana, uno a la vez.', 'Cuchara suave, plato.', '¿Cuántos alimentos nuevos probó?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 3, 'Texturas y la cuchara', 'Avanzar de papillas a texturas.', 'Pasar de purés a machacados y trozos suaves ayuda a masticar y hablar. Siempre sentado y vigilado.', 'Ofrecer un alimento machacado o en trozos suaves tres veces en la semana.', 'Tenedor para machacar.', '¿Aceptó las texturas nuevas?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 4, 'La leche sigue siendo la base', 'Mantener las tomas mientras se introducen alimentos.', 'Hasta el año, la leche sigue siendo el alimento principal; los sólidos complementan.', 'Ofrecer la leche antes de los alimentos en cada comida esta semana.', 'Ninguno.', '¿Mantuvieron las tomas habituales?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 5, 'Agua en vasito', 'Ofrecer agua simple desde los 6 meses.', 'Pequeños sorbos de agua en vaso con las comidas. Nada de jugos ni bebidas azucaradas.', 'Poner un vasito con agua en cada comida.', 'Vaso de entrenamiento.', '¿Tomó agua del vasito?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 6, 'Juego en el piso y gateo', 'Favorecer el movimiento libre.', 'El piso es el mejor lugar para moverse, rodar y gatear. Objetos a distancia invitan a desplazarse.', 'Treinta minutos de juego en el piso al día, con objetos para alcanzar.', 'Tapete, juguetes de casa.', '¿Cuántos días llegaron a 30 minutos?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 7, 'Siestas y noche', 'Ordenar el sueño de la etapa.', 'Dos o tres siestas de día y una rutina corta de noche (baño, cuento, canción) ayudan a dormir mejor.', 'Repetir la misma rutina de noche cinco días.', 'Cuento o canción.', '¿Se durmió más fácil con la rutina?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 8, 'Pantallas: todavía no', 'Mantener cero pantallas.', 'Antes de los 2 años las pantallas no aportan y restan tiempo de juego y contacto. Apagarlas durante comidas y juego.', 'Comidas y juego sin pantallas durante la semana.', 'Ninguno.', '¿Hubo pantallas cerca del bebé?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 9, 'Comer en familia a su ritmo', 'Sentar al bebé a la mesa familiar.', 'Comer con la familia, a su ritmo y sin forzar, construye una relación sana con la comida.', 'Tres comidas en familia con el bebé a la mesa.', 'Silla alta o cojín seguro.', '¿Cuántas comidas en familia lograron?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 10, 'Señales de alergia y cuándo consultar', 'Saber qué observar al introducir alimentos.', 'Ronchas, vómito, hinchazón o dificultad para respirar tras un alimento nuevo requieren atención. Anotar qué comió ayuda a identificar.', 'Llevar la lista de alimentos probados y cualquier reacción.', 'Libreta.', '¿Hubo alguna reacción que anotar?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 11, 'Rutina del día', 'Tener un día con horarios parecidos.', 'Comidas, siestas, juego y paseo a horas parecidas dan seguridad y hacen más fácil el día.', 'Escribir la rutina del día y seguirla cinco días.', 'Hoja para la rutina.', '¿La rutina funcionó la mayoría de los días?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('6-12m', 12, 'Cierre de la etapa', 'Celebrar y pasar a 1–3 años.', 'Repasamos lo construido: alimentos variados, agua, juego en el piso y sueño. Sigue la etapa 1 a 3 años.', 'Completar la evaluación de cierre y celebrar en familia.', 'Ninguno.', '¿Qué les gustaría conservar?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 1, 'Conocemos nuestros hábitos', 'Observar qué come, cuánto duerme y cuánto se mueve.', 'Esta semana observamos sin cambiar nada todavía. La idea es tener un punto de partida honesto.', 'Anotar tres días qué desayunó, comió y cenó, y cuánto durmió.', 'Libreta.', '¿Quedaron los tres días anotados?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 2, 'Desayuno sencillo', 'Empezar el día con un desayuno completo.', 'Una fruta, un cereal y una proteína. Sencillo y económico marca el ritmo del día.', 'Preparar juntos un desayuno con fruta, cereal y proteína cuatro días.', 'Ninguno.', '¿Cuántos días desayunó completo?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 3, 'Agua primero', 'Cambiar bebidas azucaradas por agua.', 'Es uno de los cambios con más efecto. Un vaso propio y ofrecer agua antes que otra bebida.', 'Tener un vaso de agua personal y ofrecerlo en cada comida.', 'Vaso propio.', '¿Pidió jugo o refresco esta semana?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 4, 'Frutas y verduras de colores', 'Probar frutas y verduras nuevas jugando.', 'Mientras más colores en el plato, más variedad de nutrientes. A esta edad probar varias veces es normal.', 'Probar una fruta o verdura nueva y señalar su color.', 'Una fruta o verdura nueva.', '¿Probó algo nuevo?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 5, 'Moverse jugando', 'Llegar a 60 minutos de juego activo al día.', 'A esta edad el movimiento es juego: correr, bailar, trepar con seguridad.', 'Tres tardes de juego activo en familia.', 'Pelota, música.', '¿Cuántas tardes jugaron activo?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 6, 'Dormir bien', 'Tener una rutina de noche corta y constante.', 'Baño, cuento, cama. A la misma hora. El sueño cambia el apetito y el ánimo.', 'Fijar una hora de dormir y cumplirla cinco noches.', 'Cuento.', '¿Cuántas noches se cumplió la hora?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 7, 'Pantallas con medida', 'Limitar pantallas a menos de una hora y acompañadas.', 'A esta edad, si hay pantallas, que sean pocas, de calidad y con un adulto. Nunca en comidas ni antes de dormir.', 'Apagar pantallas en comidas y una hora antes de dormir.', 'Ninguno.', '¿Hubo pantallas en comidas?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 8, 'Berrinches, hambre y emociones', 'Distinguir hambre de cansancio o enojo.', 'Muchos berrinches son sueño o hambre. Nombrar la emoción y ofrecer alternativas ayuda.', 'Antes de dar comida por un berrinche, revisar si es sueño o cansancio.', 'Ninguno.', '¿Lograron identificar la causa de un berrinche?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 9, 'Comer en familia', 'Compartir la mesa sin pantallas.', 'Las comidas compartidas mejoran lo que se come y la convivencia. El menor come lo mismo que la familia.', 'Tres comidas en familia en la mesa, sin pantallas.', 'Ninguno.', '¿Cuántas comidas en familia lograron?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 10, 'Dientes y cepillado', 'Cepillar los dientes dos veces al día.', 'Desde el primer diente, con un poco de pasta con flúor y ayuda de un adulto.', 'Cepillar dientes mañana y noche durante la semana.', 'Cepillo infantil.', '¿Se cepilló dos veces al día?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 11, 'Hábitos que se quedan', 'Elegir tres hábitos para conservar.', 'Repasamos qué funcionó y qué no. Elegimos los tres hábitos que la familia quiere conservar.', 'Escribir los tres hábitos elegidos y ponerlos en el refrigerador.', 'Hoja y plumón.', '¿Ya eligieron sus tres hábitos?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('1-3a', 12, 'Celebramos y seguimos', 'Cerrar el programa con reconocimiento.', 'Cierre: reconocimiento al menor y plan sencillo para los siguientes tres meses. Sigue la etapa 3 a 6 años.', 'Completar la evaluación de cierre y celebrar en familia.', 'Reconocimiento (ejemplo).', '¿Qué fue lo mejor del programa?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 1, 'Punto de partida', 'Observar hábitos sin cambiar nada.', 'Qué desayuna, qué toma, cuánto juega, a qué hora duerme y cuánto tiempo de pantallas. Punto de comparación del programa.', 'Anotar tres días los hábitos de comida, sueño, juego y pantallas.', 'Libreta.', '¿Quedaron los tres días anotados?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 2, 'Desayuno que da energía', 'Desayunar completo antes de salir.', 'El desayuno marca el ritmo del día. Ejemplos sencillos y económicos de desayunos completos.', 'Preparar juntos un desayuno con fruta, cereal y proteína.', 'Ninguno.', '¿Cuántos días desayunó completo?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 3, 'Agua en lugar de bebidas azucaradas', 'Que el agua sea la bebida principal.', 'Cambiar jugos y refrescos por agua es uno de los cambios con más efecto. Botella propia y agua en la mesa.', 'Tener una botella de agua personal y llenarla cada mañana.', 'Botella propia.', '¿Tomó agua en la escuela?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 4, 'El plato de colores', 'Comer frutas y verduras variadas.', 'Mientras más colores en el plato, más variedad de nutrientes. Juego de colores para la semana.', 'Probar una fruta o verdura nueva y dibujarla.', 'Hojas y colores.', '¿Probó algo nuevo?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 5, '60 minutos de juego activo', 'Moverse al menos una hora al día.', 'El movimiento en la infancia es juego, no ejercicio. Ideas para 60 minutos activos al día.', 'Tres tardes de juego activo en familia (pelota, bailar, escondidas).', 'Pelota.', '¿Cuántas tardes jugaron activo?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 6, 'Hora fija para dormir', 'Dormir 10 horas o más con rutina.', 'Rutina corta y hora fija. El sueño cambia el apetito, el ánimo y el aprendizaje.', 'Fijar una hora de dormir y cumplirla cinco noches.', 'Cuento.', '¿Cuántas noches se cumplió la hora?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 7, 'Acuerdos de pantallas', 'Tener reglas claras y compartidas sobre pantallas.', 'Acuerdos familiares sobre cuándo sí y cuándo no: nunca en comidas ni antes de dormir, máximo una hora.', 'Hacer un cartel de acuerdos de pantallas y pegarlo en casa.', 'Cartulina y plumones.', '¿Se cumplieron los acuerdos?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 8, 'Emociones y comida', 'Distinguir hambre de aburrimiento o enojo.', 'Nombrar la emoción antes de comer y ofrecer alternativas cuando no es hambre.', 'Nombrar la emoción antes de pedir algo de comer, durante una semana.', 'Ninguno.', '¿Lograron nombrar emociones?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 9, 'Comer en familia sin pantallas', 'Compartir la mesa.', 'Las comidas compartidas, sin pantallas, mejoran lo que se come y la convivencia.', 'Tres comidas en familia en la mesa, sin pantallas.', 'Ninguno.', '¿Cuántas comidas en familia lograron?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 10, 'El refrigerio escolar', 'Preparar un refrigerio sano para el preescolar.', 'Fruta, agua y algo sencillo. Involucrar al menor hace que lo coma.', 'Que el menor arme su refrigerio dos días con una lista de opciones.', 'Lista de opciones.', '¿Armó su refrigerio?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 11, 'Hábitos que se quedan', 'Elegir tres hábitos para conservar.', 'Repasamos qué funcionó y qué no. Elegimos los tres hábitos que la familia quiere conservar.', 'Escribir los tres hábitos elegidos y ponerlos en el refrigerador.', 'Hoja y plumón.', '¿Ya eligieron sus tres hábitos?');
insert into programa_semanas (etapa_id, numero, titulo, objetivo, contenido, actividad, materiales, checkin) values ('3-6a', 12, 'Celebración y plan', 'Cerrar el programa con reconocimiento.', 'Cierre: reconocimiento al menor y plan sencillo para los siguientes tres meses.', 'Completar la evaluación de cierre y celebrar en familia.', 'Reconocimiento (ejemplo).', '¿Qué fue lo mejor del programa?');
